mapper.select:
SELECT c.cadre_id, c.cadre_name, c.post_title, c.unit_name, o.option_content, o.option_type, COUNT(r.result_id) AS votes FROM assessment_result r LEFT JOIN assessment_cadre c ON r.cadre_id = c.cadre_id LEFT JOIN assessment_option o ON r.option_id = o.option_id LEFT JOIN assessment_activity a ON r.activity_id = a.activity_id
AND a.activity_year >= #{startYear}
AND a.activity_year <= #{endYear}
AND c.cadre_name LIKE concat('%', #{cadreName}, '%')
AND a.status != #{excludeStatus}
GROUP BY c.cadre_id, c.cadre_name, c.post_title, c.unit_name, o.option_content, o.option_type ORDER BY c.cadre_id, o.option_type, votes DESC
